class AccountMailer < ApplicationMailer
  def cancellation(cancellation)
    @account = cancellation.account
    @user = cancellation.initiated_by

    mail(
      to: @user.identity.email_address,
      subject: "Your Fizzy account was cancelled"
    )
  end

  def account_export_completed(export)
    @export = export
    @account = export.account
    @user = export.user
    @download_url = download_url_for(export)

    mail to: @user.identity.email_address, subject: "Your Fizzy account export is ready"
  end

  def account_export_failed(export)
    @export = export
    @account = export.account
    @user = export.user

    mail to: @user.identity.email_address, subject: "Your Fizzy account export failed"
  end

  def cards_export_completed(export)
