    @account = export.account
    @user = export.user

    mail to: @user.identity.email_address, subject: "Your Fizzy cards export failed"
  end

  def import_completed(import)
    @import = import
    @account = import.imported_account
    @user = import.user
    @account_url = root_url(script_name: @account.slug)

    mail to: import.identity.email_address, subject: "Your Fizzy account import is ready"
  end

  def import_failed(import)
    @import = import
    @user = import.user

    mail to: import.identity.email_address, subject: "Your Fizzy account import failed"
  end

  private
    def download_url_for(export)
      data_transfer_download_url(export.download_sgid, script_name: nil)
    end
end
